function arSeed(){
 const at='2026-10-20T02:00:00.000Z',batch={id:'AR-DEMO-2026',name:'2026年度科技创业基金征集 · 流程样例',issuer:'national',region:'all',notice:'示例通知第01号；各比例、门槛需以实际发布通知为准。此批次全部为虚构流程样本，与原Excel档案无关。',deadline:'2026-11-30',version:1,status:'published',weights:Object.fromEntries(arDimensions.map(d=>[d.id,d.weight])),gates:arClone(arGateTemplates),createdAt:at};
 const names=['启源硬科技创业基金（流程样例）','新岸医疗成长基金（流程样例）','远岑智能制造基金（流程样例）','知行半导体基金（流程样例）','青禾科技成果转化基金（流程样例）','星川跨境投资基金（流程样例）','澄明先进材料基金（流程样例）','北辰未来产业基金（流程样例）'];
 const apps=names.map((name,i)=>{const a={id:'AR-SAMPLE-'+(i+1),batch:batch.id,region:i===6?'shanghai':i===7?'beijing':'shenzhen',name,manager:'样例管理机构'+(i+1),code:'DEMO-ENTITY-'+(i+1),size:5+i,request:Number((1+i*.1).toFixed(4)),industry:['半导体','生物医药','高端装备','半导体','科技成果转化','其他','新材料','人工智能'][i],stage:i===0?'材料补正':i===1?'资格核查':i===3?'评估复核':'综合评估',owner:'样例区域经办',materials:{},gates:{},scores:{},reviews:{},issues:[],questions:[],reports:[],packets:[],conditions:[],logs:[],revision:1,createdAt:at};
 arMaterials.forEach(([id,title])=>{if(i===0&&['track','finance','lp'].includes(id))return;a.materials[id]={status:'verified',locator:'流程样例材料 / '+title+' / 第1–3页',excerpt:'【虚构样例，非真实尽调】'+title+'已按样例口径编制；主体'+a.code+'，截止2026-09-30。仅用于体验证据、评分与报审链路。',reviewer:'样例材料核验员',files:[],at}});
 if(i!==0&&i!==1)batch.gates.forEach(g=>a.gates[g.id]={status:'pass',reason:'【流程样例】按样例通知核对符合；不是对真实机构的结论。',refs:[g.id==='entity'?'identity':g.id==='policy'?'strategy':'legal'],by:'样例资格核查员',at});
 if(i>=2&&i!==5)arDimensions.forEach((d,j)=>{a.scores[d.id]={value:[4,3,4,4,3,4][j],note:'【流程样例】'+d.focus,refs:d.materials,by:'样例评估员甲',at};a.reviews[d.id]={value:i===3&&j===2?1:a.scores[d.id].value,note:'【流程样例】独立复核证据与评分口径。',refs:d.materials,by:'样例复核员乙',at}});
 if(i===1)a.issues.push({id:'SAME-NAME',text:'同名机构争议线索，主体代码尚不一致；不得直接认定违规。',owner:'合规岗',due:'2026-11-01',status:'open'});
 if(i===5)a.gates.policy={status:'fail',reason:'【虚构反例】申报方案明确为本示例通知禁止的纯境外二级证券策略。只说明与样例通知不符，不代表机构违法。',refs:['strategy'],by:'样例资格核查员',at};
 a.logs.push({at,actor:'系统样例',text:'初始化独立虚构流程案例；未改动任何真实基金档案'});return a});
 for(const submitted of [apps[4],apps[6],apps[7]]){submitted.stage='已报国家';submitted.packets.push(arMakePacket(submitted,batch,'样例区域负责领导',at))}
 return {version:1,batches:[batch],apps,logs:[]};
}
function arRead(){const raw=localStorage.getItem(arKey);if(!raw)return arSeed();const s=JSON.parse(raw);if(s.version!==1||!Array.isArray(s.batches)||!Array.isArray(s.apps))throw Error('申报评审存储格式不兼容，未覆盖原记录');return s}
let arStore,arLoadError='';
function arCommit(fn){if(arLoadError){arUI.notice=arLoadError;return false}const before=arClone(arStore);try{fn();localStorage.setItem(arKey,JSON.stringify(arStore));arUI.persistenceFailed=false;return true}catch(e){arStore=before;arUI.persistenceFailed=true;arUI.notice='保存失败，操作已撤回；请检查本机存储空间和权限。';return false}}
const arBatch=()=>arStore.batches.find(b=>b.id===arUI.batch);
