const arBatchRows=()=>arStore.apps.filter(a=>a.batch===arUI.batch&&(!arIsRegional()||a.region===arRegion()));
const arRegionName=id=>({shenzhen:'粤港澳大湾区',shanghai:'长三角',beijing:'京津冀'}[id]||id);
const arFrozen=a=>['已报国家','国家批准','附条件批准','国家不予批准','区域不予推荐'].includes(a.stage);
