const arCanAssess=a=>arCanEdit(a)&&arRole().role==='reviewer';
const arVerified=(a,id)=>a.materials[id]?.status==='verified';
function arStats(a,b=arStore.batches.find(b=>b.id===a.batch)){
 const dims=arDimensions,coverage=dims.reduce((s,d)=>s+(a.scores[d.id]&&a.scores[d.id].refs.length&&a.scores[d.id].refs.every(id=>arVerified(a,id))?b.weights[d.id]:0),0);
 const points=dims.reduce((s,d)=>s+(a.scores[d.id]&&a.scores[d.id].refs.every(id=>arVerified(a,id))?a.scores[d.id].value/5*b.weights[d.id]:0),0);
 const missing=arMaterials.filter(([id])=>!arVerified(a,id)).length,failed=b.gates.filter(g=>a.gates[g.id]?.status==='fail').length,unknown=b.gates.filter(g=>a.gates[g.id]?.status!=='pass').length;
 const conflicts=dims.filter(d=>a.scores[d.id]&&a.reviews[d.id]&&Math.abs(a.scores[d.id].value-a.reviews[d.id].value)>=2).length;
 const independent=dims.every(d=>a.reviews[d.id]&&a.reviews[d.id].by!==a.scores[d.id]?.by&&a.reviews[d.id].refs.length&&a.reviews[d.id].refs.every(id=>arVerified(a,id)));
 const open=a.issues.filter(i=>i.status==='open').length,coi=Boolean(a.recusal);
 return {coverage,points:Math.round(points*10)/10,missing,failed,unknown,conflicts,open,independent,ready:!missing&&!unknown&&coverage===100&&!conflicts&&!open&&!coi&&independent};
}
function arMakePacket(a,b,by,at=arNow()){return {id:arId('PACKET'),version:a.packets.length+1,at,by,rule:arClone(b),snapshot:arClone({...a,packets:[],questions:[],reports:[]}),stats:arStats(a,b),regionalConclusion:'建议报请国家审批；以冻结材料、复核意见与出资条件为依据。'}}
function arLog(a,text){a.revision++;a.logs.push({at:arNow(),actor:arActor(),text})}
