function arRender(){if(!arCanUse())return;if(arUI.persistenceFailed)arUI.notice='保存失败，操作已撤回；请检查本机存储空间和权限。';if(typeof fsAccount==='function'&&fsAccount()){fsRender()}else renderApplicationReview()}
