function arHome(batches){const b=arBatch();if(!b)return '<div class="ar-empty">尚无征集批次，可先建立通知与评审规则。</div>';const rows=arBatchRows(),received=rows.filter(a=>a.packets.length),ready=rows.filter(a=>arStats(a).ready&&!arFrozen(a)),pending=rows.filter(a=>arStats(a).missing||arStats(a).unknown),filtered=rows.filter(a=>(!arUI.query||(a.name+a.manager+a.code).includes(arUI.query))&&(arUI.status==='all'||(arUI.status==='received'?a.stage==='已报国家':arUI.status==='issues'?arStats(a).unknown||arStats(a).missing||arStats(a).conflicts:a.stage===arUI.status)));
 return `<div class="ar-hero"><div><small>${arIsRegional()?'投资申请处理 · 尽调评估':'投资申请处理 · 复核审批'}</small><h2>投资申请的单项审核与批量评估</h2><p>${arIsRegional()?'集中处理申报主体提交的投资申请，开展材料核查、资格审查与多维评估，并形成区域报审意见。':'集中接收区域母基金提交的待审批投资材料，支持逐项复核、批量评估、补充材料及审批处理。'}</p></div><div class="ar-steps">${['01 材料与补正','02 资格核查','03 多维评估','04 独立复核','05 区域报审','06 国家审批'].map(x=>`<span>${x}</span>`).join('')}</div></div><div class="ar-toolbar"><select id="arBatchSelect" aria-label="选择征集批次">${batches.map(x=>`<option value="${arE(x.id)}" ${x.id===b.id?'selected':''}>${arE(x.name)} · 规则v${x.version} · ${x.status==='published'?'已发布':'待发布'}</option>`).join('')}</select>${arTag('截止 '+b.deadline)}${arTag(b.issuer==='national'?'国家通知':'区域通知')}</div><div class="ar-metrics">${arMetric('本批申报',rows.length,'不与立项/已投档案混合统计')}${arMetric('材料或资格待核',pending.length,'缺失不等于不合格')}${arMetric(arIsRegional()?'具备报审条件':'待国家审批',arIsRegional()?ready.length:rows.filter(a=>a.stage==='已报国家').length,arIsRegional()?'证据、评分、复核均完整':'仅正式冻结报审版本')}${arMetric('已形成报审材料',received.length,'按申请主体去重')}</div><nav class="ar-tabs">${[['ledger','申报台账'],['assistant','AI辅助审核'],['compare','横向评估'],['rules','通知与评审规则'],['archive','审议与归档']].map(([id,label])=>arButton('tab',label,`data-tab="${id}"`,arUI.tab===id?'active':'')).join('')}</nav>${arUI.tab==='assistant'&&typeof aaPage==='function'?aaPage():arUI.tab==='rules'?arRules(b):arUI.tab==='archive'?arArchive(rows):arUI.tab==='compare'?arCompare(rows,b):`<form id="arSearch" class="ar-toolbar"><input name="query" aria-label="搜索申报" placeholder="基金、管理人或主体标识" value="${arE(arUI.query)}"><select name="status" aria-label="阶段筛选">${[['all','全部阶段'],['issues','有待核查事项'],['received','已报国家'],['附条件批准','附条件批准'],['国家批准','国家批准']].map(([v,l])=>`<option value="${v}" ${arUI.status===v?'selected':''}>${l}</option>`).join('')}</select><button>筛选</button></form><div class="ar-toolbar">${arButton('select-all','选择当前筛选结果',`data-ids="${filtered.map(a=>a.id).join(',')}"`)}<button data-aa-action="start" class="ar-primary">✦ AI辅助批量审核</button>${arButton('batch-screen','材料初筛底稿')}${arButton('batch-remind','批量生成补正清单')}${arButton('batch-export','导出勾选评审清单')}${arButton('compare-selected','对比勾选申请')}<span class="ar-note">已选 ${arUI.selected.filter(id=>rows.some(a=>a.id===id)).length} 项</span></div>${arUI.preview?arPreview():''}<section class="ar-card"><div class="ar-table-scroll"><table class="ar-table"><thead><tr><th>选择</th><th>基金 / 管理人</th><th>申报规模</th><th>材料与资格</th><th>评估 / 独立复核</th><th>当前阶段</th><th>操作</th></tr></thead><tbody>${filtered.map(a=>arRow(a)).join('')||'<tr><td colspan="7">当前条件下暂无申请</td></tr>'}</tbody></table></div></section><details class="ar-card"><summary>登记申请 / 批量导入结构化申请</summary>${arIsRegional()?arIntakeForm(b):'<p class="ar-note">国家母基金接收区域母基金提交的待审批投资材料。虚构申请由区域侧登记与评估；可切换区域审核员体验完整流程。</p>'}</details>`}`;
}
function arRow(a){const s=arStats(a),packet=a.packets.at(-1),national=!arIsRegional(),shown=national&&packet?packet.stats:s;return `<tr><td><input type="checkbox" aria-label="选择${arE(a.name)}" data-ar-select="${a.id}" ${arUI.selected.includes(a.id)?'checked':''}></td><td><span class="ar-name">${arE(a.name)}</span><small>${arE(a.manager)} · ${arRegionName(a.region)}</small><small>${arE(a.code)}</small></td><td>${a.size} 亿目标<small>申请 ${a.request} 亿</small></td><td>${national&&!packet?'区域核查中':`${arTag(shown.missing?'待核材料 '+shown.missing:'材料齐备',shown.missing?'warn':'good')}<small>${shown.failed?'存在不符合项':shown.unknown?'资格待核实':'资格已核查'}</small>`}</td><td>${national&&!packet?'尚未正式报审':`<b>${shown.coverage===100?shown.points.toFixed(1):'暂不总评'}</b><small>证据覆盖 ${shown.coverage}% · ${shown.conflicts?'分歧待复核':shown.independent?'已独立复核':'待独立复核'}</small>`}</td><td>${arTag(a.stage,a.stage.includes('批准')?'good':a.stage.includes('补正')?'warn':'')}<small>${packet?'报审v'+packet.version:'尚未报审'}</small></td><td>${arButton('open','查看材料 →',`data-id="${a.id}"`)}</td></tr>`}
function arCreateBatchForm(){return `<section class="ar-card"><h2>建立征集批次</h2><form id="arCreateBatch" class="ar-form"><label>批次名称<input name="name" required maxlength="120"></label><label>申报截止日<input name="deadline" type="date" required></label><label class="wide">通知及适用范围<textarea name="notice" required maxlength="5000" placeholder="填入正式通知编号、适用主体、资格口径、产业地域阶段要求；示例规则不代表法定门槛"></textarea></label><div class="wide ar-actions"><button class="ar-primary">保存批次草案</button></div></form></section>`}
function arRules(b){const can=arRole().version===b.issuer&&(!arIsRegional()||arRole().role==='reviewer');return `<section class="ar-card"><h2>${arE(b.name)}</h2><p>${arE(b.notice)}</p><p class="ar-note">${b.issuer==='national'?'国家统一口径；区域可核查执行，不能自行修改本通知规则。':'区域自行征集规则，不代表国家统一口径。国家审批仍需核对上级通知。'} 已发布规则冻结，新口径请新建批次，不追溯覆盖旧申请。</p><form id="arRules" class="ar-form"><label class="wide">通知正文 / 审查口径<textarea name="notice" ${b.status==='published'||!can?'disabled':''} required>${arE(b.notice)}</textarea></label>${arGateTemplates.map(g=>`<label class="wide">${g.name}<textarea name="gate-${g.id}" ${b.status==='published'||!can?'disabled':''} required>${arE(b.gates.find(x=>x.id===g.id)?.rule)}</textarea></label>`).join('')}${arDimensions.map(d=>`<label>${d.name}权重 %<input name="weight-${d.id}" type="number" min="1" max="100" value="${b.weights[d.id]}" ${b.status==='published'||!can?'disabled':''} required></label>`).join('')}<div class="wide">${b.status!=='published'&&can?'<button class="ar-primary">核对并发布规则</button>':arTag('已冻结规则 v'+b.version,'good')}</div></form><h3>评分与复核办法</h3><p class="ar-note">每维1–5分，按权重折算100分。证据不足标“未评”，不计0分、不发布完整总分；覆盖率是已具备证据的评分权重之和。参考档次：85分及以上“优”、70–85“良”、低于70“审慎”。档次不直接决定审批。两人评分差≥2分必须重核，不做简单平均。</p><div class="ar-review-scale"><span>材料与主体精确匹配</span><span>声明利益冲突与回避</span><span>初评 / 独立复核分离</span><span>所有结论引用证据</span><span>变更材料使相关结论失效</span></div><details><summary>核查参考来源与边界</summary><p class="ar-note">材料设计参考协会公开的人员登记指引中关于业绩证明的要求，但申报资格与评分以本次通知为准；登记不代表投资能力背书。</p><a href="https://fg.amac.org.cn/governmentrules_3854/zcgz_zlgz/zcgz_smjj/zcgz_smjj_glrdj/202303/t20230327_24590.html" target="_blank" rel="noopener">协会管理人登记指引第3号（参考资料） ↗</a></details></section>`}
function arIntakeForm(b){if(b.status!=='published')return '<p>请先发布并冻结本批规则，再接收申请。</p>';if(!['reviewer','reporter'].includes(arRole().role))return '<p>请由本区域经办账号登记材料。</p>';return `<form id="arIntake" class="ar-form"><label>申报基金全称<input name="name" required maxlength="160"></label><label>管理人全称<input name="manager" required maxlength="160"></label><label>主体代码 / 拟设立唯一标识<input name="code" required maxlength="80"></label><label>产业方向<input name="industry" required maxlength="80"></label><label>基金目标规模（亿元）<input name="size" type="number" min="0.0001" step="0.0001" required></label><label>申请母基金出资（亿元）<input name="request" type="number" min="0.0001" step="0.0001" required></label><button class="ar-primary">登记一项申请</button></form><hr><p class="ar-note">批量JSON：每行一个对象，字段与上方一致。同一批次按主体标识查重，整批校验成功才导入。实际材料另在材料上传；不把文件名当成内容。</p><form id="arImport"><textarea name="json" required rows="4" placeholder='[{"name":"示例基金","manager":"示例管理人","code":"唯一代码","industry":"半导体","size":5,"request":1}]'></textarea><div class="ar-actions"><button>校验并导入</button>${arButton('import-template','下载JSON模板')}</div></form>`}
function arCompare(rows,b){const selected=rows.filter(a=>arUI.selected.includes(a.id)),scope=selected.length?selected:rows;const ranked=scope.map(a=>({a,s:!arIsRegional()&&a.packets.length?a.packets.at(-1).stats:arStats(a)})).filter(x=>arIsRegional()||x.a.packets.length);ranked.sort((x,y)=>Number(y.s.ready)-Number(x.s.ready)||y.s.points-x.s.points);return `<section class="ar-card"><h2>同口径横向评估</h2><p class="ar-note">${selected.length?'仅对比勾选申请':'本批次全部可见申请'} · 规则v${b.version} · 优先展示具备完整评估条件的申请；不完整申请不参与排名。国家侧仅比较区域冻结报审版本，不采用区域最新草稿。</p><div class="ar-table-scroll"><table class="ar-table"><thead><tr><th>申请 / 完整性</th>${arDimensions.map(d=>`<th>${d.name}<small>${b.weights[d.id]}%</small></th>`).join('')}<th>总评与依据</th></tr></thead><tbody>${ranked.map(({a,s})=>{const x=!arIsRegional()&&a.packets.length?a.packets.at(-1).snapshot:a;return `<tr><td>${arButton('open',arE(a.name),`data-id="${a.id}"`)}<small>${arRegionName(a.region)} · ${s.ready?'评估条件完整':'待完善，不排名'}</small></td>${arDimensions.map(d=>`<td>${x.scores[d.id]?x.scores[d.id].value+'/5':'未评'}<div class="ar-bar"><i style="width:${(x.scores[d.id]?.value||0)*20}%"></i></div></td>`).join('')}<td>${s.coverage===100?s.points.toFixed(1):'暂不总评'}<small>覆盖${s.coverage}% / ${s.conflicts}项分歧</small>${s.ready?arTag(s.points>=85?'优':s.points>=70?'良':'审慎','good'):arTag('待核查','warn')}</td></tr>`}).join('')||'<tr><td colspan="8">暂无正式报审材料可对比</td></tr>'}</tbody></table></div><p class="ar-note">不把拟募集规模当作管理能力；不把未实现估值当作退出回款；不以材料篇幅评分。同行业与不同阶段的差异应在审议理由中说明。</p></section>`}
function arPreview(){const p=arUI.preview;return `<section class="ar-card ar-ai"><h2>${arE(p.title)}</h2><p class="ar-note">执行预览：${p.rows.length}项可处理，${p.skipped}项不属于当前范围或无可处理内容；不会自动淘汰或审批。</p>${p.rows.map(x=>`<article class="ar-packet"><b>${arE(x.name)}</b><p class="ar-note">${arE(x.text)}</p></article>`).join('')}<div class="ar-actions">${arButton('confirm-batch','确认留存本批底稿','','ar-primary')}${arButton('cancel-batch','取消')}</div></section>`}
function arDetail(a){const b=arStore.batches.find(b=>b.id===a.batch),national=!arIsRegional(),packet=a.packets.at(-1),x=national&&packet?packet.snapshot:a,s=arStats(x,b),editable=arCanEdit(a);return `<div class="ar-hero"><div><small>${arRegionName(a.region)} · ${arE(b.name)} / v${b.version}</small><h2>${arE(a.name)}</h2><p>${arE(a.manager)} · ${arE(a.code)}<br>${a.size}亿元目标规模 · 申请${a.request}亿元 · ${arE(a.industry)}</p></div><div class="ar-steps">${arTag(a.stage)}<span>材料核验 ${10-s.missing}/10</span><span>评分证据覆盖 ${s.coverage}%</span><span>${s.coverage===100?s.points.toFixed(1)+' / 100':'未完成，不总评'}</span></div></div>${national&&!packet?'<div class="ar-alert">本申请尚在区域评审，国家侧只能了解申报概况，不能替代区域制作或批准原始尽调结论。请切换区域审核员处理原始材料。</div>':national?`<div class="ar-notice">正在查看区域冻结报审材料 v${packet.version} · ${arE(packet.at)} · ${arE(packet.by)}。国家审批意见单独留存，不覆盖区域底稿。</div>`:arFrozen(a)?'<div class="ar-alert">当前材料已冻结，不能直接修改原始材料与评分。国家退回后可补正并生成新报审版本，历史版本保留。</div>':''}<nav class="ar-tabs">${[['materials','材料与补正'],['gates','资格与风险核查'],['evaluation','多维评估'],['decision','复核与审批'],['history','报告与历史']].map(([id,l])=>arButton('detail-tab',l,`data-tab="${id}"`,arUI.detail===id?'active':'')).join('')}</nav>${national&&!packet?arAudit(a):`<div class="ar-detail-grid"><div>${arUI.detail==='materials'?arMaterialsPage(x,editable):arUI.detail==='gates'?arGatesPage(x,b,arCanAssess(a)):arUI.detail==='evaluation'?arEvaluation(x,b,arCanAssess(a)):arUI.detail==='decision'?arDecision(a,x,b):arHistory(a)}</div><aside>${arAssistant(a,x,b)}<section class="ar-card"><h3>本材料待完成</h3><p class="ar-note">${s.missing}类材料待核验<br>${s.unknown}项资格未通过核查<br>${s.open}项问题待闭环<br>${s.conflicts}项评分分歧<br>${s.independent?'独立复核已留存':'独立复核未齐备'}</p><div class="ar-actions">${arButton('report','生成当前评审报告')}${arButton('export-case','导出完整材料')}</div></section></aside></div>`}`}
function arRefs(a,selected=[],ids=null){return `<div class="ar-checks">${arMaterials.filter(([id])=>(!ids||ids.includes(id))&&arVerified(a,id)).map(([id,title])=>`<label><input type="checkbox" name="refs" value="${id}" ${selected.includes(id)?'checked':''}>${title}</label>`).join('')||'<span class="ar-note">尚无已核验材料可引用</span>'}</div>`}
function arMaterialsPage(a,editable){return `<section class="ar-card"><h2>材料清单与证据核验</h2><p class="ar-note">上传 → 本机提取文字 → 核对事实摘录及页码/工作表 → 人工核验。更换材料会清除引用该材料的资格判断与评分，要求重新核查。无历史业绩可提交新设说明及替代证据，不自动作不合格处理。</p>${arMaterials.map(([id,title,required])=>{const m=a.materials[id]||{status:'missing',files:[]};return `<details><summary>${arE(title)} ${arTag({missing:'待提交',received:'已收待核验',verified:'已核验',correction:'待补正'}[m.status]||'待核验',m.status==='verified'?'good':'warn')} · 附件${m.files?.length||0}</summary><p class="ar-note">${required}</p>${editable?`<label class="ar-note">添加本机附件（单个≤20MB）<input type="file" multiple data-ar-upload="${id}"></label>`:''}<div class="ar-evidence-list">${(m.files||[]).map(f=>`<div class="ar-evidence">${arE(f.name)} · ${Math.ceil(f.size/1024)}KB ${arButton('file','下载',`data-file="${f.id}"`)}<small>SHA256 ${arE(f.hash||'浏览器未提供')}</small></div>`).join('')}</div>${typeof aaMaterialText==='function'?aaMaterialText(m):''}${editable?`<form class="ar-material-form ar-form" data-material="${id}"><label>核验状态<select name="status">${[['missing','待提交'],['received','已收待核验'],['verified','已核验'],['correction','待补正']].map(([v,l])=>`<option value="${v}" ${m.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>证据位置<input name="locator" value="${arE(m.locator)}" placeholder="材料编号、版本日期、页码/工作表单元格" maxlength="500"></label><label class="wide">事实摘录 / 补正要求<textarea name="excerpt" maxlength="8000">${arE(m.excerpt)}</textarea></label><div><button>保存材料核验</button></div></form>`:`<div class="ar-evidence">${arE(m.locator||'未登记证据位置')}<p>${arE(m.excerpt||'未录入可核查事实')}</p><small>${arE(m.reviewer||'待核验')} · ${arE(m.at||'')}</small></div>`}</details>`}).join('')}</section>${arIssues(a,editable)}`}
function arIssues(a,editable){return `<section class="ar-card"><h2>补正与核查问题</h2>${a.issues.map(i=>`<article class="ar-packet"><b>${arE(i.text)}</b><p class="ar-note">${arE(i.owner)} · 截止${arE(i.due)} · ${i.status==='open'?'待闭环':'已闭环'}</p>${i.reply?`<p>${arE(i.reply)}</p>`:''}${editable&&i.status==='open'?`<form class="ar-close-issue" data-issue="${i.id}"><textarea name="reply" required placeholder="机构回应、核查依据及闭环说明（不是只点已读）" maxlength="5000"></textarea><button>记录闭环核查</button></form>`:''}</article>`).join('')||'<p class="ar-note">暂无登记问题；不等于已经核实无风险。</p>'}${editable?`<form id="arIssue" class="ar-form"><label class="wide">问题 / 补正要求<textarea name="text" required maxlength="5000"></textarea></label><label>责任岗位<input name="owner" required maxlength="80"></label><label>截止日<input name="due" type="date" required></label><button>登记补正任务</button></form>`:''}</section>`}
function arGatesPage(a,b,editable){return `<section class="ar-card"><h2>先查硬条件，再判断疑点</h2><div class="ar-alert">“不符合本通知”与“违法违规”是不同结论。同名线索、未决争议和材料不足只进入待核查；不能由AI直接淘汰。已确认不符合也须人工记录依据、理由及告知意见。</div>${b.gates.map(g=>{const v=a.gates[g.id]||{status:'unknown',refs:[]};return `<details open><summary>${g.name} ${arTag({pass:'核查符合',fail:'核查不符合',unknown:'待核实'}[v.status],v.status==='fail'?'bad':v.status==='pass'?'good':'warn')}</summary><p class="ar-note">规则v${b.version}：${arE(g.rule)}</p>${editable?`<form class="ar-gate-form" data-gate="${g.id}"><select name="status"><option value="unknown" ${v.status==='unknown'?'selected':''}>待核实，不作淘汰结论</option><option value="pass" ${v.status==='pass'?'selected':''}>经核查符合本通知</option><option value="fail" ${v.status==='fail'?'selected':''}>经核查不符合本通知</option></select><p class="ar-note">引用已核验材料</p>${arRefs(a,v.refs)}<textarea name="reason" required maxlength="5000" placeholder="主体匹配、查询日期与来源、通知条款、机构回应及结论依据">${arE(v.reason)}</textarea><button>保存人工核查</button></form>`:`<p>${arE(v.reason||'尚未核查')}</p><p class="ar-note">${v.refs.map(id=>arE(a.materials[id]?.locator)).join('；')} · ${arE(v.by||'待核查')}</p>`}</details>`}).join('')}</section>${arIssues(a,arCanEdit(arCurrent()))}`}
function arEvaluation(a,b,editable){return `<section class="ar-card"><h2>多维度评估底稿</h2><p class="ar-note">先判断证据是否足够，再评分。分值有锚点，理由需解释优势、短板与不确定性；AI不代填人工分数。独立复核人必须与初评账号不同，模拟账号不是真实签名。</p>${arDimensions.map(d=>{const v=a.scores[d.id],r=a.reviews[d.id],conflict=v&&r&&Math.abs(v.value-r.value)>=2;return `<details ${conflict?'open':''}><summary>${d.name} · ${b.weights[d.id]}% ${arTag(v?v.value+'/5':'未评',v?'good':'warn')} ${r?arTag('复核'+r.value+'/5',conflict?'bad':'good'):arTag('待独立复核')}</summary><p>${d.focus}</p><p class="ar-note">${d.anchors}</p>${v?`<div class="ar-evidence">初评：${v.value}/5 · ${arE(v.by)}<p>${arE(v.note)}</p><small>${v.refs.map(id=>arE(a.materials[id]?.locator)).join('；')}</small></div>`:''}${r?`<div class="ar-evidence">复核：${r.value}/5 · ${arE(r.by)}<p>${arE(r.note)}</p></div>`:''}${conflict?'<div class="ar-alert">分差≥2分，必须重新核查证据并更新初评或复核意见，不能自动平均。</div>':''}${editable?`<form class="ar-score-form" data-dimension="${d.id}"><div class="ar-form"><label>本次评估身份<select name="kind"><option value="initial">初评 / 更新初评</option><option value="review">独立复核</option></select></label><label>分数<select name="value" required><option value="">选择1–5分</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n} / 5</option>`).join('')}</select></label></div>${arRefs(a,[],d.materials)}<textarea name="note" required maxlength="8000" placeholder="按评分锚点说明优势、短板、可归属能力与未解决事项；复核应回应初评理由"></textarea><button>保存证据支持的评估</button></form>`:''}</details>`}).join('')}</section>`}
function arDecision(a,x,b){
 const s=arStats(x,b),national=!arIsRegional(),leader=arRole().role==='leader',editable=arCanAssess(a);
 const regional=`<h3>利益冲突与回避</h3><p class="ar-note">${a.recusal?'本材料有回避事项：'+arE(a.recusal):'尚无已登记的回避事项；经办仍须主动声明。'}</p>${editable?`<form id="arRecusal"><textarea name="note" maxlength="2000" placeholder="登记关联关系、接触利益冲突及应回避角色；解除需写清独立复核依据"></textarea><select name="state"><option value="active">登记需回避事项（暂停报审）</option><option value="clear">独立核查后解除（留痕）</option></select><button>保存回避记录</button></form>`:''}<h3>区域报审</h3><p class="ar-note">区域审核员完成初评，评审复核员独立复核；区域负责领导核对推荐意见与出资前提，冻结材料并报请国家审批。</p>${leader&&!arFrozen(a)?arRegionalSubmitForm(a):arTag(arFrozen(a)?'区域报审材料已冻结':'请切换区域负责领导签发推荐意见','warn')}${editable&&s.failed?`<form id="arRegionalReject"><textarea name="reason" required placeholder="依据哪条通知与哪份已核验材料不予推荐，机构回应及告知意见"></textarea><button class="ar-danger">预览不予推荐意见</button></form>`:''}`;
 const nationalForm=a.stage==='已报国家'&&arRole().role==='reviewer'?`<form id="arNationalDecision" class="ar-form"><label>审批意见<select name="outcome"><option value="return">退回区域补正</option><option value="conditional">附条件批准</option><option value="approve">批准</option><option value="reject">不予批准</option></select></label><label>审议依据 / 会议编号<input name="meeting" required maxlength="200"></label><label class="wide">复核意见与审批理由<textarea name="reason" required maxlength="8000" placeholder="复核区域结论、通知口径、差异、资金安排及重要风险，不能只写同意"></textarea></label><label class="wide">附条件事项（每行一项：条件 | 责任人 | YYYY-MM-DD）<textarea name="conditions" rows="3" maxlength="8000" placeholder="完成协议保护条款修订 | 区域投资岗 | 2026-12-15"></textarea></label><label class="wide ar-checks"><span><input name="independent" type="checkbox" required> 已核查主体、证据及区域独立复核记录；审批人员无未披露利益冲突</span></label><button class="ar-primary">预览审批意见（尚未生效）</button></form>`:`<p class="ar-note">${a.stage==='已报国家'?'当前账号没有国家审批权限。':'当前阶段：'+arE(a.stage)}</p>`;
 return `<section class="ar-card"><h2>${national?'国家复核与审批':'区域复核与推荐'}</h2><div class="ar-metrics">${arMetric('核查不符合',s.failed,'需明确条款和证据')}${arMetric('待核问题',s.open,'应答、核验后闭环')}${arMetric('评分分歧',s.conflicts,'分差≥2分需重核')}${arMetric('证据覆盖',s.coverage+'%','未评不计作零分')}</div><div class="ar-alert">${s.ready?'材料具备报审的完整性条件，但不代表应当批准投资。':'尚有材料、资格、评分、独立复核、回避或问题闭环未完成。可留存报告草稿，不可报审/批准。'}</div>${national?nationalForm:regional}${arUI.decision?arDecisionPreview():''}${a.nationalDecision?`<article class="ar-packet"><h3>${arE(a.nationalDecision.outcome)}</h3><p>${arE(a.nationalDecision.reason)}</p><small>${arE(a.nationalDecision.meeting)} · ${arE(a.nationalDecision.by)} · 报审v${a.nationalDecision.packetVersion}</small></article>`:''}</section>${arConditions(a)}${arPacketHistory(a)}`;
}
function arRegionalSubmitForm(a){return `<form id="arRegionalSubmit" class="ar-form"><label>区域审议依据 / 会议编号<input name="meeting" required maxlength="200"></label><label>区域建议出资（亿元）<input name="amount" type="number" min="0.0001" max="${a.request}" step="0.0001" required value="${a.request}"></label><label class="wide">推荐理由与资金可承受性<textarea name="reason" required maxlength="8000" placeholder="综合尽调意见、评分差异、区域配置需要、可用额度与出资节奏；写清推荐而非自动同意"></textarea></label><label class="wide">建议国家关注的出资前提 / 保留事项<textarea name="prerequisites" required maxlength="5000" placeholder="例如LP募集落实、协议保护条款、关键人承诺、投后穿透报送，或说明无额外前提的依据"></textarea></label><button class="ar-primary">预览区域推荐与报审版本</button></form>`}
function arBulkDecisionPanel(){
 const regional=arIsRegional(),allowed=regional?arRole().role==='leader':arRole().role==='reviewer';if(!allowed)return '';
 const bulk=arUI.bulk;
 return `<section class="ar-card"><div class="ar-heading"><div><h2>${regional?'批次推荐报审':'批次审议'}</h2><p class="ar-note">先在台账勾选申请，再逐项填写意见。只有本阶段、要件完整的材料才能进入；不提供无理由的一键同意。</p></div>${arButton('bulk-review','审议勾选申请','','ar-primary')}</div>${bulk?`<p class="ar-note">本次可处理 ${bulk.rows.length} 项，已跳过 ${bulk.skipped} 项（非本阶段、权限不足或区域材料未完成）。</p>${bulk.ready?`<div class="ar-alert">留存前最终核对：逐项结论、依据与冻结版本如下。确认后一次性写入本机，各材料分别留痕；不会生成出资或实缴。</div>${bulk.rows.map(r=>`<article class="ar-packet"><b>${arE(r.name)} · ${arE(r.outcome==='submit'?'区域推荐报审':{approve:'国家批准',return:'退回区域补正',reject:'国家不予批准'}[r.outcome])}</b><p>${arE(r.reason)}</p><small>${arE(r.meeting)} · 工作版本${r.revision}${r.amount?' · 建议出资'+arNumber(r.amount)+'亿元':''}</small></article>`).join('')}<div class="ar-actions">${arButton('bulk-confirm','确认逐项意见并留存','','ar-primary')}${arButton('bulk-cancel','取消本批次')}</div>`:`<form id="arBulkDecision"><label class="ar-note">本次审议 / 会议依据<input name="meeting" required maxlength="200" placeholder="会议编号、授权审批依据"></label>${bulk.rows.map(r=>`<article class="ar-packet"><h3>${arE(r.name)}</h3><p class="ar-note">${arRegionName(r.region)} · ${r.stats.points}分 · 证据覆盖${r.stats.coverage}% · ${r.packet?'区域报审v'+r.packetVersion:'区域评审待报国家'}</p><div class="ar-form">${regional?`<label>建议出资（亿元）<input name="amount-${r.id}" type="number" min="0.0001" max="${r.request}" step="0.0001" required value="${r.request}"></label><label>本次意见<input value="区域推荐报请国家审批" disabled></label>`:`<label>逐项审议意见<select name="outcome-${r.id}"><option value="return">退回区域补正</option><option value="approve">国家批准</option><option value="reject">国家不予批准</option></select></label>`}<label class="wide">本项判断、证据与理由<textarea name="reason-${r.id}" required maxlength="6000" placeholder="必须针对本申请，列明证据、关键风险与审议依据"></textarea></label>${regional?`<label class="wide">出资前提 / 保留事项<textarea name="prerequisites-${r.id}" required maxlength="4000"></textarea></label>`:''}<label class="wide"><span><input name="checked-${r.id}" type="checkbox" required> 已阅本项材料及证据，无应回避利益冲突</span></label></div></article>`).join('')}<p class="ar-note">附条件批准请打开单份材料，逐条设置条件、责任人和截止日。</p><button class="ar-primary" ${bulk.rows.length?'':'disabled'}>预览逐项审议结论</button> ${arButton('bulk-cancel','取消')}</form>`}`:''}</section>`;
}
function arPrepareBulk(){
 const regional=arIsRegional();if(regional?arRole().role!=='leader':arRole().role!=='reviewer')throw Error('当前角色无批次审议权限');
 const selected=arBatchRows().filter(a=>arUI.selected.includes(a.id));if(!selected.length)throw Error('请先在台账勾选申请');
 const eligible=selected.filter(a=>regional?!arFrozen(a)&&arStats(a).ready:a.stage==='已报国家');
 arUI.bulk={regional,actor:arActor(),ready:false,skipped:selected.length-eligible.length,rows:eligible.map(a=>{const p=a.packets.at(-1);return {id:a.id,name:a.name,region:a.region,request:a.request,revision:a.revision,packet:regional?null:p?.id,packetVersion:p?.version,stats:regional?arStats(a):arStats(p.snapshot,p.rule)}})};
}
function arConfirmBulk(){
 const bulk=arUI.bulk;if(!bulk?.ready||!bulk.rows.length||bulk.actor!==arActor()||bulk.regional!==arIsRegional())throw Error('请重新核对批次意见与账号');
 for(const row of bulk.rows){const a=arStore.apps.find(a=>a.id===row.id);if(!a||a.revision!==row.revision)throw Error('申请版本已变化，请重新发起批次审议');
  if(bulk.regional){if(arRole().role!=='leader'||a.region!==arRegion()||arFrozen(a)||!arStats(a).ready)throw Error('存在不具备区域推荐条件的申请')}
  else if(arRole().role!=='reviewer'||a.stage!=='已报国家'||a.packets.at(-1)?.id!==row.packet||(row.outcome==='approve'&&!arStats(a.packets.at(-1).snapshot,a.packets.at(-1).rule).ready))throw Error('存在不能审批的材料、权限或版本变化');
 }
 const ok=arCommit(()=>{for(const row of bulk.rows){const a=arStore.apps.find(a=>a.id===row.id);
  if(bulk.regional){const b=arStore.batches.find(b=>b.id===a.batch),p=arMakePacket(a,b,arActor());p.regionalConclusion=row.reason;p.recommendation={meeting:row.meeting,amount:row.amount,prerequisites:row.prerequisites};a.packets.push(p);a.stage='已报国家';arLog(a,'批次推荐：冻结区域报审v'+p.version+'；'+row.meeting+'；'+row.reason)}
  else{const p=a.packets.at(-1),outcome={approve:'国家批准',return:'退回区域补正',reject:'国家不予批准'}[row.outcome];a.nationalDecision={outcome,reason:row.reason,meeting:row.meeting,packetVersion:p.version,by:arActor(),at:arNow()};a.stage=row.outcome==='return'?'国家退回补正':outcome;if(row.outcome==='return')a.issues.push({id:arId('ISSUE'),text:'国家退回：'+row.reason,owner:'区域评审岗',due:'待区域确认',status:'open'});arLog(a,'国家批次审议：'+outcome+'；'+row.meeting+'；'+row.reason)}
 }});if(ok){arUI.bulk=null;arUI.notice='已分别留存'+bulk.rows.length+'项审议意见；报审历史版本未覆盖，未变更出资台账。'}
}
function arDecisionPreview(){return `<div class="ar-packet"><h3>确认意见后留存</h3><p>${arE(arUI.decision.label)}</p><p>${arE(arUI.decision.reason)}</p><p class="ar-note">此为单浏览器流程模拟；不改变出资台账，不代表真实审批签章。</p><div class="ar-actions">${arButton('confirm-decision','确认留存意见','','ar-primary')}${arButton('cancel-decision','返回修改')}</div></div>`}
function arConditions(a){return `<section class="ar-card"><h2>审批条件落实</h2><p class="ar-note">附条件批准≠满足出资条件。区域经办提交完成依据，国家侧逐项复核确认；不会自动生成实缴或投资。</p><div class="ar-conditions">${a.conditions.map(c=>`<div><b>${arE(c.text)}</b><p class="ar-note">${arE(c.owner)} · ${arE(c.due)} · ${arE(c.status)}</p>${c.evidence?`<p>完成依据：${arE(c.evidence)}</p>`:''}${arIsRegional()&&['reviewer','reporter'].includes(arRole().role)&&c.status!=='国家已确认'?`<form class="ar-condition-form" data-condition="${c.id}"><textarea name="evidence" required maxlength="5000" placeholder="提交完成事实、依据材料编号与位置">${arE(c.evidence)}</textarea><button>提交完成依据</button></form>`:!arIsRegional()&&arRole().role==='reviewer'&&c.status==='待国家核验'?`<form class="ar-condition-confirm" data-condition="${c.id}"><textarea name="note" required maxlength="5000" placeholder="独立核验意见、材料位置与日期"></textarea><button>确认条件已落实</button></form>`:''}${c.review?`<small>${arE(c.review)}</small>`:''}</div>`).join('')||'<p class="ar-note">暂无审批附带条件。</p>'}</div></section>`}
function arPacketHistory(a){return `<section class="ar-card"><h2>冻结报审版本</h2>${a.packets.slice().reverse().map(p=>`<div class="ar-packet"><b>区域报审 v${p.version} · 规则v${p.rule.version}</b><p class="ar-note">${arE(p.by)} · ${arE(p.at)} · ${p.stats.points}分 / 覆盖${p.stats.coverage}%</p>${arButton('export-packet','导出该版本',`data-packet="${p.id}"`)}</div>`).join('')||'<p class="ar-note">尚未正式报请国家审批。</p>'}</section>`}
function arAudit(a){return `<section class="ar-card"><h2>流程留痕</h2>${a.logs.slice().reverse().map(l=>`<div class="ar-log"><small>${arE(l.at)} · ${arE(l.actor)}</small><p>${arE(l.text)}</p></div>`).join('')}</section>`}
function arHistory(a){return `${arPacketHistory(a)}<section class="ar-card"><h2>评审报告与分析历史</h2><div class="ar-actions">${arButton('report','生成当前评审报告','','ar-primary')}</div>${a.reports.slice().reverse().map(r=>`<div class="ar-packet"><b>${arE(r.title)}</b><p class="ar-note">${arE(r.at)} · 工作版本${r.revision}</p>${arButton('export-report','导出HTML报告',`data-report="${r.id}"`)} ${arButton('copy-report','复制正文',`data-report="${r.id}"`)}</div>`).join('')||'<p class="ar-note">暂无已留存报告</p>'}${a.questions.slice().reverse().map(q=>`<details><summary>${arE(q.question)} · ${arE(q.at.slice(0,10))}</summary><div class="ar-answer">${arE(q.answer)}</div>${arButton('copy-answer','复制',`data-answer="${q.id}"`)} ${arButton('export-answer','导出',`data-answer="${q.id}"`)}</details>`).join('')}</section>${arAudit(a)}`}
function arAssistant(a,x,b){const last=a.questions.at(-1);return `<section class="ar-card ar-ai"><small class="ar-kicker">✦ 评审助手</small><h3>让问题回到证据</h3><p class="ar-note">限定当前材料及规则v${b.version}。输出是核查底稿，不代替人工评分、法律意见或审批。</p><div class="ar-actions">${['优先核查哪些硬条件？','生成尽调访谈提纲','比较评分分歧与补正重点','检查资金与策略可行性'].map(q=>arButton('ask-preset',q,`data-prompt="${q}"`)).join('')}</div><form id="arAsk"><label class="ar-note" for="arQuestion">自由提问 / 继续追问</label><textarea id="arQuestion" name="question" required maxlength="3000" placeholder="例如：团队业绩如何验证？这份申请还有哪些审批前提？"></textarea><button class="ar-primary">生成证据核查底稿</button></form>${last?`<details open><summary>最近一次分析</summary><div class="ar-answer">${arE(last.answer)}</div>${arButton('copy-answer','复制',`data-answer="${last.id}"`)} ${arButton('export-answer','导出',`data-answer="${last.id}"`)}</details>`:''}<p class="ar-note">历史 ${a.questions.length} 条 · 在“报告与历史”查看。附件内容是待核验数据，不作为系统指令。</p></section>`}
function arAnalyze(a,b,q){const s=arStats(a,b),lines=[`问题：${q}`,`对象：${a.name} / ${a.code}；通知规则v${b.version}。`,`【规则式底稿，非模型判断】未联网核查，未解析附件正文；仅使用人工录入的已核验事实。`];
 lines.push(`一、核查优先级：${s.failed}项已登记不符合、${s.unknown}项未完成符合性核查、${s.missing}类材料待核验、${s.open}项问题未闭环。`);
 for(const g of b.gates){const v=a.gates[g.id];lines.push(`• ${g.name}：${v?{pass:'人工核查符合',fail:'人工核查不符合',unknown:'待核实'}[v.status]:'待核实'}。规则：${g.rule}${v?.reason?'\n  底稿：'+v.reason:''}`)}
 const relevant=arDimensions.filter(d=>/团队|业绩/.test(q)?['team','track'].includes(d.id):/资金|策略|规划/.test(q)?['plan','layout','terms'].includes(d.id):/分歧|评分/.test(q)?a.scores[d.id]||a.reviews[d.id]:true);
 lines.push('二、证据与尽调追问：');for(const d of relevant){lines.push(`• ${d.name}：${d.focus}`);for(const id of d.materials){const m=a.materials[id],title=arMaterials.find(x=>x[0]===id)[1];lines.push(arVerified(a,id)?`  [证据 ${id}] ${m.locator}；摘录：${m.excerpt.slice(0,350)}`:`  [缺口 ${id}] 补充${title}，明确期间、口径、主体与出处。`)}const v=a.scores[d.id],r=a.reviews[d.id];if(v&&r&&Math.abs(v.value-r.value)>=2)lines.push(`  [分歧] 初评${v.value} / 复核${r.value}，复查同一证据的口径与期间，不取平均数。`)}
 lines.push('三、建议下一步：'+(s.ready?'由区域领导核对资金承受能力、会议依据与推荐条件后正式报审；国家以冻结版本复核，不直接采用分数自动批准。':'先完成材料补正、主体匹配、未决问题和独立复核，再形成推荐意见。'), '四、边界：不能从同名争议推定违规；不能从无记录推定无风险；新团队无历史业绩须评估替代证据；没有逐笔现金流不计算IRR；不以承诺募资替代实缴。', '自定义问题如超出已核验资料或本地规则能力，应提交补充材料或交给专业评审，不输出无依据事实。');return lines.join('\n');}
function arVisibleSnapshot(a){return !arIsRegional()&&a.packets.length?a.packets.at(-1).snapshot:a}
function arBuildReport(a){const x=arVisibleSnapshot(a),b=!arIsRegional()&&a.packets.length?a.packets.at(-1).rule:arStore.batches.find(b=>b.id===a.batch),s=arStats(x,b);return {id:arId('REPORT'),title:a.name+' / 评审报告 v'+(a.reports.length+1),at:arNow(),revision:a.revision,snapshot:arClone(x),rule:arClone(b),text:[a.name+' 申报评审报告','规则v'+b.version+'；'+(s.ready?'评估要件完整，待人工审议':'工作草稿：评审要件尚未齐备'),`目标规模${a.size}亿 / 申请${a.request}亿；均不代表实缴。`,`证据覆盖${s.coverage}% / ${s.coverage===100?'加权得分'+s.points:'不发布完整总分'}`,arAnalyze(x,b,'综合核查与审批前提'),...arDimensions.map(d=>`${d.name}（${b.weights[d.id]}%）：${x.scores[d.id]?x.scores[d.id].value+'/5；'+x.scores[d.id].note:'未评'}；复核：${x.reviews[d.id]?x.reviews[d.id].value+'/5；'+x.reviews[d.id].note:'待独立复核'}`),'未闭环问题：',...x.issues.filter(i=>i.status==='open').map(i=>i.text),a.nationalDecision?'国家意见：'+a.nationalDecision.outcome+'；'+a.nationalDecision.reason:'尚无国家审批意见',...a.conditions.map(c=>'审批条件：'+c.text+' / '+c.status),'本地流程演示，未调用模型、未联网核查；人工专业复核和真实审批签章不可替代。'].join('\n\n')}}
function arHtmlReport(r){return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${arE(r.title)}</title><style>body{max-width:960px;margin:50px auto;padding:24px;font:15px/1.9 system-ui;color:#193a59}h1{font-size:27px}pre{white-space:pre-wrap;font:inherit}small{color:#6a8298}@media print{body{margin:0}}</style><h1>${arE(r.title)}</h1><small>生成时间 ${arE(r.at)} · 工作版本 ${r.revision} · 规则v${r.rule.version}</small><pre>${arE(r.text)}</pre></html>`}
function arArchive(rows){return `<section class="ar-card"><h2>审议结论与审批后条件</h2><p class="ar-note">审批只记录流程结论，不自动把申报基金转为已出资、已实缴档案。</p>${rows.filter(a=>a.nationalDecision||a.stage==='区域不予推荐').map(a=>`<article class="ar-packet"><h3>${arE(a.name)} ${arTag(a.stage)}</h3><p>${arE(a.nationalDecision?.reason||a.regionalRejection?.reason)}</p><p class="ar-note">${a.conditions.length}项条件 · ${a.conditions.filter(c=>c.status==='国家已确认').length}项已落实</p>${arButton('open','查看审议材料',`data-id="${a.id}"`)}</article>`).join('')||'<p class="ar-empty">暂无最终审议记录；可先从区域样例材料体验评估与报审。</p>'}</section>`}
function arFileStore(mode,id,value){return new Promise((resolve,reject)=>{const req=indexedDB.open('diki-public-application-evidence-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onerror=()=>reject(req.error);req.onsuccess=()=>{const db=req.result,tx=db.transaction('files',mode),store=tx.objectStore('files'),op=mode==='readwrite'?store.put(value,id):store.get(id);let result;op.onsuccess=()=>result=op.result;tx.oncomplete=()=>{db.close();resolve(result)};tx.onerror=()=>{db.close();reject(tx.error)}}})}
async function arCopy(text){try{await navigator.clipboard.writeText(text);arUI.notice='已复制正文'}catch{arUI.notice='浏览器未授权复制，可改用导出保存'}arRender()}
function arNewApplication(v,b){return {id:arId('APP'),batch:b.id,region:arRegion(),name:v.name.trim(),manager:v.manager.trim(),code:v.code.trim().toUpperCase(),industry:v.industry.trim(),size:Number(v.size),request:Number(v.request),stage:'材料接收',owner:arActor(),materials:{},gates:{},scores:{},reviews:{},issues:[],questions:[],reports:[],packets:[],conditions:[],logs:[{at:arNow(),actor:arActor(),text:'登记虚构申请，绑定已发布规则v'+b.version}],revision:1,createdAt:arNow()}}
function arValidateIntake(list,b){if(!arIsRegional()||!['reviewer','reporter'].includes(arRole().role)||b?.status!=='published')throw Error('当前角色或批次不能接收申请');if(!Array.isArray(list)||!list.length||list.length>200)throw Error('每批导入1–200项申请');const seen=new Set(arStore.apps.filter(a=>a.batch===b.id).map(a=>a.code));for(const v of list){if(['name','manager','code','industry'].some(k=>typeof v[k]!=='string'||!v[k].trim()||v[k].length>200)||typeof v.size==='boolean'||!Number.isFinite(Number(v.size))||Number(v.size)<=0||!Number.isFinite(Number(v.request))||Number(v.request)<=0||Number(v.request)>Number(v.size))throw Error('名称、主体代码与产业必填，规模及申请额应有效且申请额不超过规模');const code=v.code.trim().toUpperCase();if(seen.has(code))throw Error('同批次主体标识重复：'+code+'。请打开原材料补正，不重复申报。');seen.add(code)}}
function arError(message){arUI.notice=message;arRender()}
function arApplyDecision(){const a=arCurrent(),d=arUI.decision;if(!a||!d||d.id!==a.id||d.revision!==a.revision)throw Error('工作版本已变化，请重新预览意见');const b=arStore.batches.find(b=>b.id===a.batch);
 if(d.kind==='submit'){if(!arIsRegional()||arRole().role!=='leader'||a.region!==arRegion()||arFrozen(a)||!arStats(a,b).ready)throw Error('仅本区域领导可签发完整、无未决事项的材料');arCommit(()=>{const p=arMakePacket(a,b,arActor());p.regionalConclusion=d.reason;p.recommendation={meeting:d.meeting||'样例审议依据',amount:d.amount??a.request,prerequisites:d.prerequisites||'按冻结材料核查出资条件'};a.packets.push(p);a.stage='已报国家';arLog(a,'区域领导冻结报审v'+p.version+'；'+d.reason)});
 }else if(d.kind==='regional-reject'){if(!arCanAssess(a)||!arStats(a,b).failed)throw Error('不予推荐需区域经核查的不符合项');arCommit(()=>{a.stage='区域不予推荐';a.regionalRejection={reason:d.reason,by:arActor(),at:arNow()};arLog(a,'区域不予推荐：'+d.reason)});
 }else {if(arRole().version!=='national'||arRole().role!=='reviewer'||a.stage!=='已报国家'||a.packets.at(-1)?.id!==d.packet)throw Error('当前无国家审批权限或材料版本变化');const p=a.packets.at(-1);if(['approve','conditional'].includes(d.outcome)&&!arStats(p.snapshot,p.rule).ready)throw Error('报审要件未齐备，不可批准');arCommit(()=>{const outcome={return:'退回区域补正',conditional:'附条件批准',approve:'国家批准',reject:'国家不予批准'}[d.outcome];a.nationalDecision={...d,outcome,packetVersion:p.version,by:arActor(),at:arNow()};if(d.outcome==='return'){a.stage='国家退回补正';a.issues.push({id:arId('ISSUE'),text:'国家退回：'+d.reason,owner:'区域评审岗',due:'待区域确认',status:'open'})}else a.stage=outcome;if(d.outcome==='conditional')a.conditions=d.conditions.map(c=>({...c,id:arId('COND'),status:'待区域落实'}));arLog(a,'国家对区域报审v'+p.version+'留存意见：'+outcome+'；'+d.reason)});
 }arUI.decision=null;if(!arUI.notice.startsWith('保存失败'))arUI.notice='意见已留存，原始报审版本保持不变，未改变实缴或投资台账。';}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-ar-action]');if(!button||!arCanUse())return;const action=button.dataset.arAction,a=arCurrent(),b=arBatch();try{
 if(action==='toggle-create')arUI.create=!arUI.create;
 else if(action==='back'){arUI.id=null;arUI.decision=null}
 else if(action==='open'){arUI.id=button.dataset.id;arUI.detail='materials';arUI.decision=null;arUI.notice=''}
 else if(action==='tab'){arUI.tab=button.dataset.tab;arUI.preview=null}
 else if(action==='detail-tab'){arUI.detail=button.dataset.tab;arUI.decision=null}
 else if(action==='select-all'){arUI.selected=button.dataset.ids.split(',').filter(Boolean);arUI.bulk=null;arUI.preview=null}
 else if(action==='compare-selected')arUI.tab='compare';
 else if(action==='bulk-review')arPrepareBulk();
 else if(action==='bulk-confirm')arConfirmBulk();
 else if(action==='bulk-cancel')arUI.bulk=null;
 else if(['batch-screen','batch-remind'].includes(action)){const selected=arBatchRows().filter(a=>arUI.selected.includes(a.id));if(!selected.length)throw Error('请先勾选要处理的申请');const eligible=selected.filter(a=>arIsRegional()?arCanEdit(a):a.stage==='已报国家');arUI.preview={kind:action,title:action==='batch-screen'?'AI批量初筛 · 留存前预览':'补正清单 · 留存前预览',skipped:selected.length-eligible.length,rows:eligible.map(a=>{const x=arVisibleSnapshot(a),s=arStats(x,b);return {id:a.id,revision:a.revision,name:a.name,text:action==='batch-screen'?`已登记不符合${s.failed}项；待核查资格${s.unknown}项；缺核验材料${s.missing}类；分歧${s.conflicts}项。${s.failed?'需人工审查不符合依据，不自动淘汰。':'未完成核查不等于合格或违规。'}`:arMaterials.filter(([id])=>!arVerified(x,id)).map(([,title])=>title).join('；')||'无材料缺口；仍需核查未决事项与独立复核。'}})};}
 else if(action==='confirm-batch'){const p=arUI.preview;if(!p?.rows.length)throw Error('没有可留存的申请');for(const row of p.rows){const x=arStore.apps.find(a=>a.id===row.id);if(!x||x.revision!==row.revision||(arIsRegional()?!arCanEdit(x):x.stage!=='已报国家'))throw Error('申请状态已变化，请重新预览')}arCommit(()=>p.rows.forEach(row=>{const x=arStore.apps.find(a=>a.id===row.id);x.questions.push({id:arId('Q'),question:p.title,answer:row.text,at:arNow()});arLog(x,p.title+'；只留存核查底稿，未改变评分或审批')}));arUI.preview=null;arUI.notice='批量底稿已分别留存在各材料分析历史中。'}
 else if(action==='cancel-batch')arUI.preview=null;
 else if(action==='batch-export'){const rows=arBatchRows().filter(a=>arUI.selected.includes(a.id));if(!rows.length)throw Error('请先勾选申请');download('申报评审清单.csv','\uFEFF'+[['基金','主体代码','区域','阶段','覆盖率','得分（完整时）','不符合项','待核资格'].join(','),...rows.map(a=>{const s=arStats(arVisibleSnapshot(a),b),notReceived=!arIsRegional()&&!a.packets.length;return [a.name,a.code,arRegionName(a.region),a.stage,notReceived?'未正式报审':s.coverage,notReceived?'未正式报审':s.coverage===100?s.points:'待评',notReceived?'未正式报审':s.failed,notReceived?'未正式报审':s.unknown].map(v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"').join(',')})].join('\r\n'),'text/csv;charset=utf-8')}
 else if(action==='import-template')download('申报批量导入模板.json',JSON.stringify([{name:'示例科技创业基金',manager:'示例管理人',code:'DEMO-UNIQUE-001',industry:'半导体',size:5,request:1}],null,2),'application/json');
 else if(action==='ask-preset'){if(!a)throw Error('请选择材料');arSaveQuestion(a,button.dataset.prompt)}
 else if(action==='report'){if(!a)throw Error('请选择材料');if(!arIsRegional()&&!a.packets.length)throw Error('尚未正式报审');arCommit(()=>{a.reports.push(arBuildReport(a));a.logs.push({at:arNow(),actor:arActor(),text:'冻结当前评审报告版本'})});arUI.detail='history';arUI.notice='已生成可导出的评审报告；未完成核验的内容明确标为草稿。'}
 else if(action==='export-case'){if(!a)return;download(a.name+'_完整流程材料.json',JSON.stringify(a,null,2),'application/json')}
 else if(action==='export-packet'){const p=a?.packets.find(p=>p.id===button.dataset.packet);if(p)download(a.name+'_报审v'+p.version+'.json',JSON.stringify(p,null,2),'application/json')}
 else if(['copy-answer','export-answer'].includes(action)){const q=a?.questions.find(q=>q.id===button.dataset.answer);if(q){if(action==='copy-answer')return arCopy(q.question+'\n'+q.answer);download(a.name+'_分析.txt',q.question+'\n'+q.answer,'text/plain;charset=utf-8')}}
 else if(['copy-report','export-report'].includes(action)){const r=a?.reports.find(r=>r.id===button.dataset.report);if(r){if(action==='copy-report')return arCopy(r.text);download(a.name+'_评审报告.html',arHtmlReport(r),'text/html;charset=utf-8')}}
 else if(action==='submit-packet'){if(!a||!arIsRegional()||arRole().role!=='leader'||arFrozen(a)||!arStats(a,b).ready)throw Error('需区域领导账号，且材料、资格、独立复核及问题闭环齐备');arUI.decision={kind:'submit',id:a.id,revision:a.revision,label:'冻结报审v'+(a.packets.length+1)+'并正式报请国家审批',reason:'经区域复核，建议报请国家审批；依据本材料规则、已核验证据及双人评估结论。'};}
 else if(action==='confirm-decision')arApplyDecision();
 else if(action==='cancel-decision')arUI.decision=null;
 else if(action==='file'){const file=await arFileStore('readonly',button.dataset.file);if(!file)throw Error('本机附件不存在或已被浏览器清理');const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=file.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 arRender();if(['back','open'].includes(action))window.scrollTo({top:0});
 }catch(e){arError(e.message)}});
function arSaveQuestion(a,question){const x=arVisibleSnapshot(a),b=arStore.batches.find(b=>b.id===a.batch);if(!arIsRegional()&&!a.packets.length)throw Error('尚未正式报审');arCommit(()=>a.questions.push({id:arId('Q'),question,answer:arAnalyze(x,b,question),at:arNow()}))}
document.addEventListener('change',async event=>{
 const input=event.target;
 if(input.matches('[data-ar-select]')){
  if(input.checked)arUI.selected=[...new Set([...arUI.selected,input.dataset.arSelect])];else arUI.selected=arUI.selected.filter(id=>id!==input.dataset.arSelect);
  arUI.bulk=null;arUI.preview=null;arRender();return;
 }
 if(input.id==='arBatchSelect'){arUI.batch=input.value;arUI.selected=[];arUI.preview=null;arUI.bulk=null;arRender();return}
 if(!input.matches('[data-ar-upload]'))return;
 const a=arCurrent();if(!a||!arCanEdit(a))return;
 const files=[...input.files],id=input.dataset.arUpload,actor=arActor();let expectedRevision=a.revision;
 const form=input.closest('details')?.querySelector('.ar-material-form'),draft=form?Object.fromEntries(new FormData(form)):{};
 input.disabled=true;
 try{let count=0;for(const file of files){
   if(file.size>20*1024*1024)throw Error('单个附件不得超过20MB');
   const fileId=arId('FILE'),buffer=await file.arrayBuffer(),hash=crypto.subtle?[...new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))].map(x=>x.toString(16).padStart(2,'0')).join(''):'';
   if(!arCanEdit(a)||arActor()!==actor||a.revision!==expectedRevision)throw Error('账号、材料或工作版本已变化，请重新上传');
   const extracted=typeof pfExtract==='function'?await pfExtract(file).then(r=>({name:file.name,fileId,text:r.text.slice(0,50000),parser:r.parser,truncated:r.truncated||r.text.length>50000})).catch(e=>({name:file.name,fileId,text:'',error:e.message})):null;
   if(!arCanEdit(a)||arActor()!==actor||a.revision!==expectedRevision)throw Error('解析期间工作版本已变化，请重新上传');
   await arFileStore('readwrite',fileId,file);
   if(!arCanEdit(a)||arActor()!==actor||a.revision!==expectedRevision)throw Error('账号、材料或工作版本已变化，未更新材料核验状态');
   if(!arCommit(()=>{const m={...(a.materials[id]||{files:[]}),...draft};m.files=[...(m.files||[]),{id:fileId,name:file.name,size:file.size,type:file.type,hash,at:arNow()}];m.extracted=[...(m.extracted||[]),...(extracted?[extracted]:[])];m.status='received';a.materials[id]=m;arInvalidate(a,id);arLog(a,'收到附件：'+file.name+'；本机文字提取结果待人工核验')}))break;
   expectedRevision=a.revision;count++;
  }
  arUI.notice='已保存'+count+'个本机附件。请核对本机提取结果，录入事实与位置后人工核验。';arRender();
 }catch(e){arError(e.message)}
});
document.addEventListener('submit',event=>{const f=event.target;if(!f.matches('#arCreateBatch,#arRules,#arIntake,#arImport,#arSearch,#arAsk,#arIssue,#arRecusal,#arNationalDecision,#arRegionalReject,#arRegionalSubmit,.ar-material-form,.ar-gate-form,.ar-score-form,.ar-close-issue,.ar-condition-form,.ar-condition-confirm'))return;event.preventDefault();if(!arCanUse()||!f.reportValidity())return;const fd=new FormData(f),v=Object.fromEntries(fd),a=arCurrent(),b=arBatch();try{
 if(f.id==='arSearch'){arUI.query=v.query.trim();arUI.status=v.status}
 else if(f.id==='arCreateBatch'){if(arIsRegional()&&arRole().role!=='reviewer')throw Error('请使用区域审核员发布征集');if(!v.name.trim()||!v.notice.trim())throw Error('批次名称和通知不能为空');const batch={id:arId('BATCH'),name:v.name.trim(),deadline:v.deadline,notice:v.notice.trim(),issuer:arRole().version,region:arIsRegional()?arRegion():'all',version:1,status:'draft',weights:Object.fromEntries(arDimensions.map(d=>[d.id,d.weight])),gates:arClone(arGateTemplates),createdAt:arNow()};if(arCommit(()=>arStore.batches.push(batch))){arUI.batch=batch.id;arUI.tab='rules';arUI.create=false}}
 else if(f.id==='arRules'){if(!b||b.status==='published'||b.issuer!==arRole().version||(arIsRegional()&&arRole().role!=='reviewer'))throw Error('已发布规则冻结，或当前无权修改');const weights=Object.fromEntries(arDimensions.map(d=>[d.id,Number(v['weight-'+d.id])]));if(Object.values(weights).some(n=>!Number.isFinite(n)||n<=0)||Object.values(weights).reduce((s,n)=>s+n,0)!==100)throw Error('各维度权重必须大于0且合计100%');if(!v.notice.trim()||b.gates.some(g=>!v['gate-'+g.id]?.trim()))throw Error('通知与资格规则须完整');arCommit(()=>{b.weights=weights;b.notice=v.notice.trim();b.gates.forEach(g=>g.rule=v['gate-'+g.id].trim());b.status='published';b.publishedAt=arNow();b.publishedBy=arActor()});arUI.notice='通知与规则已发布并冻结，可开始接收虚构申请。'}
 else if(f.id==='arIntake'||f.id==='arImport'){const rows=f.id==='arImport'?JSON.parse(v.json):[v];arValidateIntake(rows,b);arCommit(()=>rows.forEach(row=>arStore.apps.push(arNewApplication(row,b))));arUI.notice='已登记'+rows.length+'项申请，按主体标识查重；尚未完成资格核查。'}
 else if(!a)throw Error('未找到当前可见材料');
 else if(f.id==='arAsk'){if(!v.question.trim())throw Error('请输入问题');arSaveQuestion(a,v.question.trim())}
 else if(f.matches('.ar-material-form')){if(!arCanEdit(a))throw Error('当前不能修改原始材料');if(!['missing','received','verified','correction'].includes(v.status))throw Error('无效材料状态');if(v.status==='verified'&&arRole().role!=='reviewer')throw Error('材料提交人不能自行核验，请设为已收待核验，交由区域审核员核查');if(v.status==='verified'&&(!v.locator.trim()||!v.excerpt.trim()))throw Error('核验必须填写事实摘录与证据位置；有附件不等于已核验');const id=f.dataset.material;arCommit(()=>{a.materials[id]={...(a.materials[id]||{files:[]}),...v,reviewer:arActor(),at:arNow()};arInvalidate(a,id);arLog(a,'更新材料核验：'+id+'；引用该材料的结论需重新核查')})}
 else if(f.matches('.ar-gate-form')){if(!arCanAssess(a)||a.recusal)throw Error('仅未回避的区域审核员可核查资格');const refs=fd.getAll('refs');if(!['unknown','pass','fail'].includes(v.status)||!v.reason.trim())throw Error('请填写有效核查意见');if(v.status!=='unknown'&&(!refs.length||refs.some(id=>!arVerified(a,id))))throw Error('符合/不符合结论须引用已核验材料');arCommit(()=>{a.gates[f.dataset.gate]={...v,refs,by:arActor(),at:arNow()};a.stage='资格核查';arLog(a,'更新资格核查：'+f.dataset.gate+' / '+v.status)})}
 else if(f.matches('.ar-score-form')){if(!arCanAssess(a)||a.recusal)throw Error('仅未回避的区域审核员可评估');const id=f.dataset.dimension,dim=arDimensions.find(d=>d.id===id),refs=fd.getAll('refs'),value=Number(v.value),review=v.kind==='review';if(!dim||!Number.isInteger(value)||value<1||value>5||!v.note.trim()||!refs.length||refs.some(id=>!dim.materials.includes(id)||!arVerified(a,id)))throw Error('评分须1–5分、具体理由及已核验的本维度材料');if(review&&(!a.scores[id]||a.scores[id].by===arActor()))throw Error('独立复核须由不同于初评的演示账号进行');arCommit(()=>{(review?a.reviews:a.scores)[id]={value,note:v.note.trim(),refs,by:arActor(),at:arNow()};if(!review)delete a.reviews[id];a.stage='评估复核';arLog(a,(review?'独立复核':'初评')+'：'+dim.name+' / '+value+'分')})}
 else if(f.id==='arIssue'){if(!arCanEdit(a))throw Error('当前不能登记原始补正');if(!v.text.trim()||!v.owner.trim())throw Error('请填写问题及责任岗位');arCommit(()=>{a.issues.push({...v,id:arId('ISSUE'),status:'open'});arLog(a,'登记补正问题：'+v.text)})}
 else if(f.matches('.ar-close-issue')){if(!arCanAssess(a))throw Error('补正闭环需区域审核员核验');if(!v.reply.trim())throw Error('请填写闭环核查依据');arCommit(()=>{const i=a.issues.find(i=>i.id===f.dataset.issue);if(!i)throw Error('问题不存在');Object.assign(i,{reply:v.reply.trim(),status:'closed',by:arActor(),at:arNow()});arLog(a,'核查闭环：'+i.text)})}
 else if(f.id==='arRecusal'){if(!arCanAssess(a)||!v.note.trim())throw Error('请由区域审核员填写回避/解除依据');arCommit(()=>{a.recusal=v.state==='active'?v.note.trim():null;arLog(a,(v.state==='active'?'登记回避：':'核查解除回避：')+v.note)})}
 else if(f.id==='arRegionalSubmit'){if(!arIsRegional()||arRole().role!=='leader'||arFrozen(a)||!arStats(a,b).ready)throw Error('仅区域领导可签发完整且无未决事项的材料');if(!v.meeting.trim()||!v.reason.trim()||!v.prerequisites.trim()||!Number.isFinite(Number(v.amount))||Number(v.amount)<=0||Number(v.amount)>a.request)throw Error('请补齐审议依据、推荐理由、出资前提；建议额须大于0且不超过申请额');arUI.decision={kind:'submit',id:a.id,revision:a.revision,meeting:v.meeting.trim(),amount:Number(v.amount),prerequisites:v.prerequisites.trim(),label:'冻结报审v'+(a.packets.length+1)+'；建议出资'+arNumber(v.amount)+'亿元',reason:v.reason.trim()}}
 else if(f.id==='arRegionalReject'){if(!arCanAssess(a)||!arStats(a,b).failed||!v.reason.trim())throw Error('需已核查的不符合项及具体意见');arUI.decision={kind:'regional-reject',id:a.id,revision:a.revision,label:'区域不予推荐，保留申报及核查证据',reason:v.reason.trim()}}
 else if(f.id==='arNationalDecision'){if(arRole().version!=='national'||arRole().role!=='reviewer'||a.stage!=='已报国家')throw Error('当前账号/阶段无国家审批权限');if(!['return','approve','conditional','reject'].includes(v.outcome)||!v.reason.trim()||!v.meeting.trim()||!fd.has('independent'))throw Error('请补齐审议依据、复核理由及独立性确认');const conditions=v.conditions.trim()?v.conditions.trim().split('\n').filter(Boolean).map(line=>{const [text,owner,due]=line.split('|').map(x=>x.trim());if(!text||!owner||!/^\d{4}-\d{2}-\d{2}$/.test(due||'')||Number.isNaN(Date.parse(due))||new Date(due).toISOString().slice(0,10)!==due)throw Error('每条条件须按“条件 | 责任人 | 有效日期”填写');return {text,owner,due}}):[];if(v.outcome==='conditional'&&!conditions.length)throw Error('附条件批准至少登记一项有责任人和期限的条件');if(v.outcome!=='conditional'&&conditions.length)throw Error('已输入附带条件，请选择附条件批准，或清空条件');arUI.decision={kind:'national',id:a.id,revision:a.revision,packet:a.packets.at(-1).id,outcome:v.outcome,label:{return:'退回区域补正',approve:'国家批准',conditional:'附条件批准',reject:'不予批准'}[v.outcome],reason:v.reason.trim(),meeting:v.meeting.trim(),conditions}}
 else if(f.matches('.ar-condition-form')){if(!arIsRegional()||!['reviewer','reporter'].includes(arRole().role)||!v.evidence.trim())throw Error('请由区域经办填写条件完成依据');arCommit(()=>{const c=a.conditions.find(c=>c.id===f.dataset.condition);if(!c||c.status==='国家已确认')throw Error('条件已冻结或不存在');c.evidence=v.evidence.trim();c.status='待国家核验';arLog(a,'提交条件完成依据：'+c.text)})}
 else if(f.matches('.ar-condition-confirm')){if(arRole().version!=='national'||arRole().role!=='reviewer'||!v.note.trim())throw Error('请由国家审核员填写核验依据');arCommit(()=>{const c=a.conditions.find(c=>c.id===f.dataset.condition);if(!c||c.status!=='待国家核验')throw Error('条件尚未提交依据');c.status='国家已确认';c.review=v.note.trim()+' / '+arActor();arLog(a,'国家核验条件：'+c.text)})}
 arRender();
 }catch(e){arError(e.message)}});
document.addEventListener('submit',event=>{
 const f=event.target;if(f.id!=='arBulkDecision')return;event.preventDefault();if(!f.reportValidity())return;
 try{const data=new FormData(f),bulk=arUI.bulk;if(!bulk||bulk.actor!==arActor()||!arCanUse())throw Error('当前批次或角色已变化');const meeting=String(data.get('meeting')||'').trim();if(!meeting)throw Error('请填写本次审议依据');
  const rows=bulk.rows.map(r=>{const reason=String(data.get('reason-'+r.id)||'').trim();if(!reason||!data.has('checked-'+r.id))throw Error('每份材料必须填写理由并确认已阅证据及独立性');const row={...r,reason,meeting};
   if(bulk.regional){row.outcome='submit';row.amount=Number(data.get('amount-'+r.id));row.prerequisites=String(data.get('prerequisites-'+r.id)||'').trim();if(!Number.isFinite(row.amount)||row.amount<=0||row.amount>r.request||!row.prerequisites)throw Error('建议额应有效且不超过申请额；出资前提须完整')}
   else{row.outcome=data.get('outcome-'+r.id);if(!['approve','return','reject'].includes(row.outcome))throw Error('无效审批意见');if(row.outcome==='approve'&&!r.stats.ready)throw Error('要件不完整，不能批准，可退回补正')}
   return row;
  });arUI.bulk={...bulk,rows,ready:true};arRender();
 }catch(e){arError(e.message)}
});
